/**
 * T2-D unit tests for the security service's row → domain converters.
 * Pure functions: take a DB row shape, return a domain object. No IO.
 */

import { describe, it, expect } from 'vitest';
import {
  parseJson,
  parseJsonArray,
  rowToAuditLog,
  rowToSecurityEvent,
  rowToApiKey,
} from '../converters';

// Stub for the encrypted-details decryptor — returns the same shape the
// real implementation does (parsed plaintext JSON, or null if absent).
const stubDecrypt = (stored: unknown, _auditId: string): Record<string, unknown> | null => {
  if (stored == null || stored === '') return null;
  if (typeof stored === 'string') {
    try { return JSON.parse(stored); } catch { return null; }
  }
  return stored as Record<string, unknown>;
};

describe('parseJson()', () => {
  it('returns {} for null/undefined/empty', () => {
    expect(parseJson(null)).toEqual({});
    expect(parseJson(undefined)).toEqual({});
    expect(parseJson('')).toEqual({});
  });

  it('parses a JSON string', () => {
    expect(parseJson('{"a":1,"b":"x"}')).toEqual({ a: 1, b: 'x' });
  });

  it('returns {} on malformed JSON instead of throwing', () => {
    expect(parseJson('not json')).toEqual({});
    expect(parseJson('{broken')).toEqual({});
  });

  it('passes through an already-parsed object', () => {
    const obj = { foo: 'bar' };
    expect(parseJson(obj)).toBe(obj);
  });
});

describe('parseJsonArray()', () => {
  it('returns [] for null/undefined/empty', () => {
    expect(parseJsonArray(null)).toEqual([]);
    expect(parseJsonArray(undefined)).toEqual([]);
  });

  it('parses a JSON array string', () => {
    expect(parseJsonArray('["a","b","c"]')).toEqual(['a', 'b', 'c']);
  });

  it('returns [] on malformed JSON', () => {
    expect(parseJsonArray('[broken')).toEqual([]);
  });

  it('passes through an already-array value', () => {
    expect(parseJsonArray(['x', 'y'])).toEqual(['x', 'y']);
  });

  it('returns [] for non-string non-array (e.g. object)', () => {
    expect(parseJsonArray({ a: 1 })).toEqual([]);
  });
});

describe('rowToAuditLog()', () => {
  it('maps the load-bearing fields from a row', () => {
    const row = {
      id: 'audit_1',
      user_id: 'user_1',
      organization_id: 'org_1',
      action: 'auth.login',
      resource_type: 'session',
      resource_id: null,
      ip_address: '10.0.0.1',
      user_agent: 'curl/8.7',
      details: '{"path":"/api/auth/login","status":200}',
      previous_state: null,
      new_state: null,
      success: true,
      error_message: null,
      created_at: '2026-04-27T22:00:00.000Z',
    };
    const log = rowToAuditLog(row, stubDecrypt);
    expect(log.id).toBe('audit_1');
    expect(log.userId).toBe('user_1');
    expect(log.organizationId).toBe('org_1');
    expect(log.action).toBe('auth.login');
    expect(log.resourceType).toBe('session');
    expect(log.resourceId).toBeUndefined(); // null → undefined
    expect(log.ipAddress).toBe('10.0.0.1');
    expect(log.success).toBe(true);
    expect(log.createdAt).toBeInstanceOf(Date);
    // details: plaintext JSON falls back through decryptDetails plaintext path
    expect(typeof log.details).toBe('object');
  });

  it('coerces null user_id and organization_id to undefined', () => {
    const row = {
      id: 'a', user_id: null, organization_id: null,
      action: 'x', resource_type: 'y', resource_id: null,
      ip_address: null, user_agent: null,
      details: null, previous_state: null, new_state: null,
      success: false, error_message: 'err', created_at: '2026-01-01',
    };
    const log = rowToAuditLog(row, stubDecrypt);
    expect(log.userId).toBeUndefined();
    expect(log.organizationId).toBeUndefined();
    expect(log.success).toBe(false);
    expect(log.errorMessage).toBe('err');
  });
});

describe('rowToSecurityEvent()', () => {
  it('maps event fields and parses details JSON', () => {
    const row = {
      id: 'evt_1', event_type: 'failed_login', severity: 'high',
      source: 'auth', user_id: 'u1', ip_address: '1.2.3.4',
      details: '{"attempts":5}', resolved: false,
      resolved_at: null, resolved_by: null,
      created_at: '2026-04-01T00:00:00Z',
    };
    const e = rowToSecurityEvent(row);
    expect(e.eventType).toBe('failed_login');
    expect(e.severity).toBe('high');
    expect(e.details).toEqual({ attempts: 5 });
    expect(e.resolved).toBe(false);
    expect(e.resolvedAt).toBeUndefined();
  });
});

describe('rowToApiKey()', () => {
  it('maps key fields and parses scopes array', () => {
    const row = {
      id: 'key_1', organization_id: 'org_1', name: 'connector-1',
      key_hash: 'h', key_prefix: 'sk_t_',
      scopes: '["read:docs","write:certs"]',
      rate_limit: '100', rate_limit_window: '60',
      last_used_at: null, usage_count: '0', is_active: true,
      expires_at: null, created_at: '2026-04-01T00:00:00Z',
    };
    const k = rowToApiKey(row);
    expect(k.scopes).toEqual(['read:docs', 'write:certs']);
    expect(k.rateLimit).toBe(100);
    expect(k.rateLimitWindow).toBe(60);
    expect(k.usageCount).toBe(0);
    expect(k.isActive).toBe(true);
    expect(k.lastUsedAt).toBeUndefined();
  });
});
